from wandb.sdk.internal.datastore import DataStore
from wandb.proto import wandb_internal_pb2
import json

def extract_history(run_dir):
    ds = DataStore()
    wandb_file = [f for f in __import__('os').listdir(run_dir) if f.endswith('.wandb')][0]
    ds.open_for_scan(f'{run_dir}/{wandb_file}')

    history = []
    while True:
        data = ds.scan_data()
        if data is None:
            break
        record = wandb_internal_pb2.Record()
        try:
            record.ParseFromString(data)
            if record.HasField('history'):
                h = record.history
                item = {'_step': h.step.num if h.HasField('step') else None}
                for kv in h.item:
                    key = kv.nested_key if kv.nested_key else kv.key
                    if kv.HasField('value_json'):
                        try:
                            item[key] = json.loads(kv.value_json)
                        except:
                            item[key] = kv.value_json
                if len(item) > 1:
                    history.append(item)
        except:
            pass
    return history

