from wandb.sdk.internal.datastore import DataStore
from wandb.proto import wandb_internal_pb2
import json, os

def extract_wandb_history(run_dir):
    ds = DataStore()
    wandb_files = [f for f in os.listdir(run_dir) if f.endswith('.wandb')]
    if not wandb_files:
        return []
    ds.open_for_scan(os.path.join(run_dir, wandb_files[0]))
    history = []
    while True:
        data = ds.scan_data()
        if data is None:
            break
        record = wandb_internal_pb2.Record()
        record.ParseFromString(data)
        if record.HasField('history'):
            h = record.history
            item = {'_step': h.step.num}
            for kv in h.item:
                key = kv.nested_key[0] if kv.nested_key else kv.key
                try:
                    item[key] = json.loads(kv.value_json)
                except:
                    item[key] = kv.value_json
            history.append(item)
    return history

